package org.kanger;
import java.util.*;
import org.kanger.enums.QueryPass;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalFrozenConstraints.*;
import org.kanger.ContextUniversalFrozenConstraints.Result;
import org.kanger.ContextUniversalInputResiduals.Residual;
import org.kanger.ContextWitnessResultTransport.*;

/** Native negative application recipes retain the sign and complete simultaneous donor binding. */
public final class ContextUniversalSignedFixedApplicationsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalNativeRows.Result rows(Snapshot x,Snapshot a){ContextUniversalNativeRows.Result r=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(r.classified&&r.withinShape,r.reason);return r;}
    static Result close(Snapshot x,Snapshot a,Packet p,PrivatePool pool,int depth){Result r=ContextUniversalFrozenConstraints.closeSignedFixedApplications(rows(x,a),p,pool,null,16,depth,512,256,WORK);require(r.closed&&r.signedApplications&&r.applications,r.reason);ContextUniversalFrozenConstraints.check(r,depth,()->{});Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof proof:r.proofs)audit(proof,seen);return r;}
    static void audit(Proof p,Set<Proof> seen){if(!seen.add(p))return;require(p.exchanged==null,"flattened/owning proof has no imported frame");if(p.original!=null){require(p.original.parts.contains(p.part)&&p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source)),"actual original whole Source0");return;}if(p.input!=null){require(p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof),"actual carried signed proof and grade");return;}Set<Source> sources=new HashSet<>();int depth;Residual expected;
        if(p.producer!=null){audit(p.producer,seen);sources.addAll(p.producer.support.sources);depth=p.producer.support.depth;List<Residual> donors=new ArrayList<>();for(Proof donor:p.donors){audit(donor,seen);sources.addAll(donor.support.sources);depth=Math.max(depth,donor.support.depth);donors.add(donor.clause);}expected=p.conclusion<0?ContextUniversalInputResiduals.applyFixedPositiveUnits(p.producer.clause,donors,()->{}):ContextUniversalInputResiduals.applyFixedSignedUnits(p.producer.clause,p.conclusion,donors,()->{});require(expected!=null&&expected.variables.isEmpty(),"genuinely fixed signed application");}
        else{audit(p.unit,seen);audit(p.horn,seen);sources.addAll(p.unit.support.sources);sources.addAll(p.horn.support.sources);depth=Math.max(p.unit.support.depth,p.horn.support.depth);expected=ContextUniversalInputResiduals.resolveSignedUnit(p.unit.clause,p.horn.clause,p.pivot,()->{});}
        require(p.clause==null?expected==null:expected!=null&&p.clause.equivalent(expected,()->{}),"independent principal signed recipe replay");require(p.support.depth==depth+1&&p.support.sources.equals(sources),"all actual parent Sources, one max-parent step");
    }
    static Proof unit(Result r,String name,boolean sign){return r.proofs.stream().filter(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals(name)&&p.clause.literals.get(0).positive==sign).findFirst().get();}
    static ConstraintTransfer transfer(Result r,Packet p,PrivatePool pool,int depth){ConstraintTransfer t=pool==null?ContextWitnessResultTransport.transferConstraints(r,p,depth,WORK):ContextWitnessResultTransport.transferConstraintsPrivate(r,pool,depth,WORK);require(t.transferred,t.reason);require(ContextUniversalSignedProductAudit.bind(r,t,65536,WORK).bound,"exact signed product audit");return t;}
    static Application nativeEvent(String[] statements,Source[] sources,String name,boolean sign)throws Exception{User user=new User();Mind mind=new Mind(user);user.setCurrentMind(mind);try(ContextProductionCapture c=ContextProductionCapture.begin(mind,10000)){for(int i=0;i<statements.length;++i)c.replay(mind,sources[i],statements[i]);mind.setQueryPass(QueryPass.CHECK);mind.link(null,false);require(!mind.analyze(null,false),"native fixture consistent");ContextProductionCapture.Snapshot captured=c.snapshot();require(captured.gaps.isEmpty(),"complete ordinary native capture");return captured.applications.stream().filter(e->e.conclusion.predicate.equals(name)&&e.conclusion.positive==sign).findFirst().get();}}
    static void nativeAgreement(Proof proof,Application e){require(e.steps==1&&proof.support.depth==1&&proof.clause.equivalent(ContextUniversalInputResiduals.fact(e.conclusion,()->{}),()->{}),"actual native signed result and one-step grade agree");Set<Source> sources=new HashSet<>();for(Support p:e.producerSupports){require(p.depth==0,"native producer0");sources.addAll(p.sources);}for(Proof donor:proof.donors){require(donor.support.depth==0,"actual native fixture donor0");sources.addAll(donor.support.sources);require(e.premises.stream().anyMatch(f->donor.clause.equivalent(ContextUniversalInputResiduals.fact(f,()->{}),()->{})),"every signed donor appears in actual native event");}require(sources.equals(proof.support.sources)&&e.premises.size()==proof.donors.size(),"same complete actual donor/producer Sources");}
    static void counterexamples()throws Exception {
        String rule="!@w left(w)&&right(w)->p(w);",right="!right(1);",np="!~p(1);";Snapshot x=bind(true,"!anchor(1); "+rule),a=bind(false,right+np);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result old=ContextUniversalFrozenConstraints.closeSignedApplications(rows(x,a),common,null,null,16,16,512,256,WORK);require(old.closed&&!old.signedApplications&&unit(old,"left",false).support.depth==2,"old positive-only application mode preserves negative recipe2");require(!ContextWitnessResultTransport.transferConstraints(old,common,1,WORK).transferred,"old accepted fact bound1 refuses");Result r=close(x,a,common,null,1);Proof negative=unit(r,"left",false);require(negative.conclusion>=0&&negative.donors.stream().anyMatch(p->!p.clause.literals.get(0).positive)&&negative.support.sources.size()==3,"negative result has actual negative donor and all three Sources");nativeAgreement(negative,nativeEvent(new String[]{rule,right,np},new Source[]{ContextPrivateWitnessPoolRunner.source(x,rule),ContextPrivateWitnessPoolRunner.source(a,right),ContextPrivateWitnessPoolRunner.source(a,np)},"left",false));transfer(r,common,null,1);
        String nr="!@w p(w)&&q(w)->~r(w);",p="!p(1);",q="!q(1);";Snapshot owner=bind(true,p+q),forbid=bind(false,nr);Packet cp=ContextPrivateWitnessPoolRunner.common(owner);Proof out=unit(close(owner,forbid,cp,null,1),"r",false);require(out.donors.stream().allMatch(d->d.clause.literals.get(0).positive),"headless constraint gives negative conclusion using positive fixed donors");nativeAgreement(out,nativeEvent(new String[]{nr,p,q},new Source[]{ContextPrivateWitnessPoolRunner.source(forbid,nr),ContextPrivateWitnessPoolRunner.source(owner,p),ContextPrivateWitnessPoolRunner.source(owner,q)},"r",false));
        Snapshot positive=bind(false,"!@w p(w)&&q(w)->r(w);");Result positiveResult=close(owner,positive,cp,null,1);require(unit(positiveResult,"r",true).support.depth==1,"new signed mode includes positive applications unchanged");transfer(positiveResult,cp,null,1);
        Result bounded=ContextUniversalFrozenConstraints.closeSignedFixedApplications(rows(x,a),common,null,null,1,16,512,256,WORK);require(!bounded.closed&&bounded.proofs.isEmpty(),"round limit no partial signed application proofs");bounded=ContextUniversalFrozenConstraints.closeSignedFixedApplications(rows(x,a),common,null,null,16,16,512,256,1);require(!bounded.closed&&bounded.proofs.isEmpty(),"work limit no prefix");require(!ContextWitnessResultTransport.transferConstraints(r,common,0,WORK).transferred,"fact bound0 refuses actual one-step result");
    }
    static void bindingsAndAlternatives()throws Exception {
        Snapshot x=bind(true,"!$w p(w,1)&&q(w,1);"),a=bind(false,"!@w p(w,1)&&q(w,1)->~r(w,1);");Packet cp=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,a,cp,null,1);Proof negative=unit(r,"r",false);require(negative.clause.origins.size()==1&&negative.support.depth==1&&negative.support.sources.size()==2,"negative result preserves co-bound physical Origin/whole seed Source");transfer(r,cp,null,1);
        Snapshot split=bind(true,"!$w p(w,1); !$w q(w,1);");Result distinct=close(split,a,ContextPrivateWitnessPoolRunner.common(split),null,16);require(distinct.proofs.stream().noneMatch(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals("r")),"different Origins cannot be joined by signed application");
        Snapshot owner=bind(true,"!anchor(1); !@w p(w,1)&&q(w,1)->~r(w,1);"),seed=bind(false,"!$w p(w,1)&&q(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(owner);PrivatePool pool=ContextWitnessResultTransport.privatePool(common,owner,seed,WORK);ConstraintTransfer t=transfer(close(owner,seed,common,pool,1),common,pool,1);require(t.output.items.stream().anyMatch(i->i.atom.predicate.equals("r")&&!i.atom.positive)&&t.output.items.stream().noneMatch(i->i.atom.predicate.equals("p")||i.atom.predicate.equals("q")),"private fixed signed binding shares only X-dependent negative result");
        Snapshot cx=bind(true,"!p(1,2); !~q(2,1);"),bad=bind(false,"!@u @v p(u,v)&&r(u,v)->q(u,v);"),good=bind(false,"!@u @v p(u,v)&&r(u,v)->q(v,u);");Packet base=ContextPrivateWitnessPoolRunner.common(cx);Result no=close(cx,bad,base,null,16);require(no.proofs.stream().noneMatch(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals("r")),"one binding across positive and negative donors");require(unit(close(cx,good,base,null,1),"r",false).support.depth==1,"crossed signed two-variable binding works");
        Snapshot ax=bind(true,"!anchor(1); !@w left(w)&&right(w)->p(w);"),donors=bind(false,"!right(1); !~p(1);"),loop=bind(false,"!@w left(w)->left(w);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(donors,loop),WORK);Packet input=ContextPrivateWitnessPoolRunner.common(ax);Result alts=close(ax,group,input,null,16);ConstraintTransfer produced=transfer(alts,input,null,2);Item left=produced.output.items.stream().filter(i->i.atom.predicate.equals("left")&&!i.atom.positive).findFirst().get();require(left.proofs.size()==2&&left.proofs.stream().anyMatch(p->p.depth==1&&p.sources.size()==3)&&left.proofs.stream().anyMatch(p->p.depth==2&&p.sources.size()==4),"deeper Source superset retained beside base negative1");require(!ContextWitnessResultTransport.transferConstraints(alts,input,1,WORK).transferred,"different Source minimum cannot hide deeper obligation");Snapshot reverse=ContextProductionNativeBinding.trusted("own",Arrays.asList(loop,donors),WORK);require(ContextWitnessResultTransport.sameContents(produced.output,transfer(close(ax,reverse,input,null,16),input,null,2).output,WORK),"member order does not change signed minima");
    }
    static void rejectionAndScope()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,"!@w p(w)&&q(w)->~r(w);"),b=bind(false,"!r(1);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b),WORK);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,group,common,null,16);require(r.xRefuted&&r.emptyProofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.size()==4),"negative application1 yields checked empty2, no false empty1");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof proof:ContextUniversalFrozenConstraints.rejectionEvidence(r,WORK))audit(proof,seen);require(seen.stream().anyMatch(p->p.producer!=null&&p.conclusion>=0),"flattened rejection retains selected signed conclusion recipe");require(!ContextWitnessResultTransport.transferConstraints(r,common,16,WORK).transferred,"refuted signed application frame cannot publish");
        Snapshot symbolic=bind(true,"!anchor(1); !@w p(w); !@w q(w);"),negative=bind(false,"!@w p(w)&&q(w)->~r(w);");Result open=close(symbolic,negative,ContextPrivateWitnessPoolRunner.common(symbolic),null,16);Proof unit=unit(open,"r",false);require(unit.producer==null&&!unit.clause.variables.isEmpty()&&unit.support.depth==2,"symbolic donors remain binary, no finite-domain sampling or unproved grade1");
    }
    static void historicalAndSymbolic()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w right(w)&&seed(w)->p(w);"),a=bind(false,"!seed(1); !~p(1);");Packet initial=ContextPrivateWitnessPoolRunner.common(x);Packet carried=transfer(close(x,a,initial,null,16),initial,null,1).output;Snapshot b=bind(false,"!left(1); !@w left(w)&&target(w)->right(w);");Result r=close(x,b,carried,null,16);Proof target=unit(r,"target",false);require(target.producer!=null&&target.support.depth==2&&target.support.sources.size()==5&&target.donors.stream().anyMatch(p->p.input!=null&&p.support.depth==1&&!p.clause.literals.get(0).positive),"actual carried negative1 donor gives signed application2/full five Sources without reset");transfer(r,carried,null,2);
        Snapshot owner=bind(true,"!p(1); !q(1); !@v top(v);"),producer=bind(false,"!@w p(w)&&q(w)->~r(w); !@w @v ~r(w)&&top(v)->~s(w,v);");Packet common=ContextPrivateWitnessPoolRunner.common(owner);Map<Cut,Result> checksByCut=new LinkedHashMap<>();checksByCut.put(Cut.of(owner),close(owner,null,common,null,16));checksByCut.put(Cut.of(producer),close(owner,producer,common,null,16));ContextUniversalSignedUnitExchange.Collection collected=ContextUniversalSignedUnitExchange.collect(owner,common,new ArrayList<>(checksByCut.keySet()),checksByCut,512,256,16,WORK);require(collected.collected,collected.reason);require(collected.output.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("s")&&!u.clause.literals.get(0).positive&&u.support.depth==2&&u.owner.signedApplications),"signed application-backed symbolic negative keeps owning mode/grade");
        Snapshot opinion=bind(false,"!@w @v s(w,v);");Result consumer=ContextUniversalFrozenConstraints.closeSignedUnits(rows(owner,opinion),common,null,collected.output,16,16,512,256,WORK);require(consumer.closed&&consumer.xRefuted&&!consumer.signedApplications,consumer.reason);ContextUniversalFrozenConstraints.check(consumer,16,()->{});require(consumer.emptyProofs.stream().anyMatch(p->p.support.depth==3&&p.support.sources.size()==6),"legacy binary consumer checks historical signed owner and derives exact empty3");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof proof:ContextUniversalFrozenConstraints.rejectionEvidence(consumer,WORK))audit(proof,seen);require(seen.stream().anyMatch(p->p.producer!=null&&p.conclusion>=0&&!p.clause.literals.get(0).positive),"flattened imported evidence retains real selected negative recipe without owner frame");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("signed-fixed-applications-").toString());counterexamples();bindingsAndAlternatives();rejectionAndScope();historicalAndSymbolic();System.out.println("CONTEXT_UNIVERSAL_SIGNED_FIXED_APPLICATIONS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
